-- Thai national curriculum Arts indicators, P1-P3. OBEC 2021 must-know/should-know guide.
begin;
WITH seed(grade,standard_code,code,seq,classification,name) AS (VALUES
('P1','ศ 1.1','ARTS-P1-01',1,'must_know','อภิปรายเกี่ยวกับรูปร่าง ลักษณะ และขนาดของสิ่งต่าง ๆ รอบตัวในธรรมชาติและสิ่งที่มนุษย์สร้างขึ้น'),
('P1','ศ 1.1','ARTS-P1-02',2,'should_know','บอกความรู้สึกที่มีต่อธรรมชาติและสิ่งแวดล้อมรอบตัว'),
('P1','ศ 1.1','ARTS-P1-03',3,'must_know','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์สร้างงานทัศนศิลป์'),
('P1','ศ 1.1','ARTS-P1-04',4,'should_know','สร้างงานทัศนศิลป์โดยการทดลองใช้สีด้วยเทคนิคง่าย ๆ'),
('P1','ศ 1.1','ARTS-P1-05',5,'must_know','วาดภาพระบายสีภาพธรรมชาติตามความรู้สึกของตนเอง'),
('P1','ศ 1.2','ARTS-P1-06',6,'must_know','ระบุงานทัศนศิลป์ในชีวิตประจำวัน'),
('P1','ศ 2.1','ARTS-P1-07',7,'must_know','รู้ว่าสิ่งต่าง ๆ สามารถก่อกำเนิดเสียงที่แตกต่างกัน'),
('P1','ศ 2.1','ARTS-P1-08',8,'must_know','บอกลักษณะของเสียงดัง - เบา และความช้า - เร็วของจังหวะ'),
('P1','ศ 2.1','ARTS-P1-09',9,'should_know','ท่องบทกลอน ร้องเพลงง่าย ๆ'),
('P1','ศ 2.1','ARTS-P1-10',10,'must_know','มีส่วนร่วมในกิจกรรมดนตรีอย่างสนุกสนาน'),
('P1','ศ 2.1','ARTS-P1-11',11,'must_know','บอกความเกี่ยวข้องของเพลงที่ใช้ในชีวิตประจำวัน'),
('P1','ศ 2.2','ARTS-P1-12',12,'should_know','เล่าถึงเพลงในท้องถิ่น'),
('P1','ศ 2.2','ARTS-P1-13',13,'should_know','ระบุสิ่งที่ชื่นชอบในดนตรีท้องถิ่น'),
('P1','ศ 3.1','ARTS-P1-14',14,'must_know','เลียนแบบการเคลื่อนไหว'),
('P1','ศ 3.1','ARTS-P1-15',15,'must_know','แสดงท่าทางง่าย ๆ เพื่อสื่อความหมายแทนคำพูด'),
('P1','ศ 3.1','ARTS-P1-16',16,'must_know','บอกสิ่งที่ตนเองชอบ จากการดูหรือร่วมการแสดง'),
('P1','ศ 3.2','ARTS-P1-17',17,'must_know','ระบุและเล่นการละเล่นของเด็กไทย'),
('P1','ศ 3.2','ARTS-P1-18',18,'must_know','บอกสิ่งที่ตนเองชอบในการแสดงนาฏศิลป์'),
('P2','ศ 1.1','ARTS-P2-01',1,'must_know','บรรยายรูปร่าง รูปทรงที่พบในธรรมชาติและสิ่งแวดล้อม'),
('P2','ศ 1.1','ARTS-P2-02',2,'must_know','ระบุทัศนธาตุที่อยู่ในสิ่งแวดล้อม และงานทัศนศิลป์ โดยเน้นเรื่องเส้น สี รูปร่าง และรูปทรง'),
('P2','ศ 1.1','ARTS-P2-03',3,'should_know','สร้างงานทัศนศิลป์ต่าง ๆ โดยใช้ทัศนธาตุที่เน้นเส้น รูปร่าง'),
('P2','ศ 1.1','ARTS-P2-04',4,'must_know','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์ สร้างงานทัศนศิลป์ ๓ มิติ'),
('P2','ศ 1.1','ARTS-P2-05',5,'should_know','สร้างภาพปะติดโดยการตัดหรือฉีกกระดาษ'),
('P2','ศ 1.1','ARTS-P2-06',6,'must_know','วาดภาพเพื่อถ่ายทอดเรื่องราวเกี่ยวกับครอบครัวของตนเองและเพื่อนบ้าน'),
('P2','ศ 1.1','ARTS-P2-07',7,'should_know','เลือกงานทัศนศิลป์ และบรรยายถึงสิ่งที่มองเห็น รวมถึงเนื้อหาเรื่องราว'),
('P2','ศ 1.1','ARTS-P2-08',8,'should_know','สร้างสรรค์งานทัศนศิลป์เป็นรูปแบบงานโครงสร้างเคลื่อนไหว'),
('P2','ศ 1.2','ARTS-P2-09',9,'should_know','บอกความสำคัญของงานทัศนศิลป์ที่พบเห็นในชีวิตประจำวัน'),
('P2','ศ 1.2','ARTS-P2-10',10,'should_know','อภิปรายเกี่ยวกับงานทัศนศิลป์ประเภทต่าง ๆ ในท้องถิ่นโดยเน้นถึงวิธีการสร้างงานและวัสดุอุปกรณ์ที่ใช้'),
('P2','ศ 2.1','ARTS-P2-11',11,'must_know','จำแนกแหล่งกำเนิดของเสียงที่ได้ยิน'),
('P2','ศ 2.1','ARTS-P2-12',12,'must_know','จำแนกคุณสมบัติของเสียงสูง - ต่ำ ดัง - เบา ยาว - สั้น ของดนตรี'),
('P2','ศ 2.1','ARTS-P2-13',13,'must_know','เคาะจังหวะหรือเคลื่อนไหวร่างกายให้สอดคล้องกับเนื้อหาของเพลง'),
('P2','ศ 2.1','ARTS-P2-14',14,'should_know','ร้องเพลงง่าย ๆ ที่เหมาะสมกับวัย'),
('P2','ศ 2.1','ARTS-P2-15',15,'must_know','บอกความหมายและความสำคัญของเพลงที่ได้ยิน'),
('P2','ศ 2.2','ARTS-P2-16',16,'should_know','บอกความสัมพันธ์ของเสียงร้อง เสียงเครื่องดนตรีในเพลงท้องถิ่น โดยใช้คำง่าย ๆ'),
('P2','ศ 2.2','ARTS-P2-17',17,'should_know','แสดงและเข้าร่วมกิจกรรมทางดนตรีในท้องถิ่น'),
('P2','ศ 3.1','ARTS-P2-18',18,'must_know','เคลื่อนไหวขณะอยู่กับที่และเคลื่อนที่'),
('P2','ศ 3.1','ARTS-P2-19',19,'should_know','แสดงการเคลื่อนไหวที่สะท้อนอารมณ์ของตนเองอย่างอิสระ'),
('P2','ศ 3.1','ARTS-P2-20',20,'must_know','แสดงท่าทาง เพื่อสื่อความหมายแทนคำพูด'),
('P2','ศ 3.1','ARTS-P2-21',21,'must_know','แสดงท่าทางประกอบจังหวะอย่างสร้างสรรค์'),
('P2','ศ 3.2','ARTS-P2-22',22,'should_know','ระบุมารยาทในการชมการแสดง'),
('P2','ศ 3.2','ARTS-P2-23',23,'should_know','ระบุและเล่นการละเล่นพื้นบ้าน'),
('P2','ศ 3.2','ARTS-P2-24',24,'must_know','เชื่อมโยงสิ่งที่พบเห็นในการละเล่นพื้นบ้านกับสิ่งที่พบเห็นในการดำรงชีวิตของคนไทย'),
('P2','ศ 3.2','ARTS-P2-25',25,'should_know','ระบุสิ่งที่ชื่นชอบและภาคภูมิใจในการละเล่นพื้นบ้าน'),
('P3','ศ 1.1','ARTS-P3-01',1,'should_know','บรรยายรูปร่าง รูปทรงในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์'),
('P3','ศ 1.1','ARTS-P3-02',2,'should_know','วาดภาพถ่ายทอดความคิด ความรู้สึกจากเหตุการณ์ชีวิตจริง โดยใช้เส้น รูปร่าง รูปทรง สี และพื้นผิว'),
('P3','ศ 1.1','ARTS-P3-03',3,'should_know','ระบุวัสดุ อุปกรณ์ที่ใช้สร้างผลงานเมื่อชมงานทัศนศิลป์'),
('P3','ศ 1.1','ARTS-P3-04',4,'should_know','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์สร้างสรรค์งานปั้น'),
('P3','ศ 1.1','ARTS-P3-05',5,'should_know','บรรยายเหตุผลและวิธีการในการสร้างงานทัศนศิลป์ โดยเน้นถึงเทคนิค และวัสดุ อุปกรณ์'),
('P3','ศ 1.1','ARTS-P3-06',6,'must_know','จำแนกทัศนธาตุของสิ่งต่าง ๆ ในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์ โดยเน้นเรื่องเส้น สี รูปร่าง รูปทรง และพื้นผิว'),
('P3','ศ 1.1','ARTS-P3-07',7,'must_know','วาดภาพ ระบายสีสิ่งของรอบตัว'),
('P3','ศ 1.1','ARTS-P3-08',8,'must_know','ระบุสิ่งที่ชื่นชมและสิ่งที่ควรปรับปรุงในงานทัศนศิลป์ของตนเอง'),
('P3','ศ 1.1','ARTS-P3-09',9,'should_know','ระบุและจัดกลุ่มของภาพตามทัศนธาตุที่เน้นในงานทัศนศิลป์นั้น ๆ'),
('P3','ศ 1.1','ARTS-P3-10',10,'should_know','บรรยายลักษณะรูปร่าง รูปทรงในงานการออกแบบสิ่งต่าง ๆ ที่มีในบ้านและโรงเรียน'),
('P3','ศ 1.2','ARTS-P3-11',11,'must_know','เล่าถึงที่มาของงานทัศนศิลป์ในท้องถิ่น'),
('P3','ศ 1.2','ARTS-P3-12',12,'should_know','อธิบายเกี่ยวกับวัสดุอุปกรณ์และวิธีการสร้างงานทัศนศิลป์ในท้องถิ่น'),
('P3','ศ 2.1','ARTS-P3-13',13,'must_know','ระบุรูปร่างลักษณะของเครื่องดนตรีที่เห็นและได้ยินในชีวิตประจำวัน'),
('P3','ศ 2.1','ARTS-P3-14',14,'must_know','ใช้รูปภาพหรือสัญลักษณ์แทนเสียงและจังหวะเคาะ'),
('P3','ศ 2.1','ARTS-P3-15',15,'must_know','บอกบทบาทหน้าที่ของเพลงที่ได้ยิน'),
('P3','ศ 2.1','ARTS-P3-16',16,'must_know','ขับร้องและบรรเลงดนตรีง่าย ๆ'),
('P3','ศ 2.1','ARTS-P3-17',17,'must_know','แสดงความคิดเห็นเกี่ยวกับเสียงดนตรี เสียงขับร้องของตนเองและผู้อื่น'),
('P3','ศ 2.1','ARTS-P3-18',18,'should_know','เคลื่อนไหวท่าทางสอดคล้องกับอารมณ์ของเพลงที่ฟัง'),
('P3','ศ 2.1','ARTS-P3-19',19,'should_know','นำดนตรีไปใช้ในชีวิตประจำวันหรือโอกาสต่าง ๆ ได้อย่างเหมาะสม'),
('P3','ศ 2.2','ARTS-P3-20',20,'should_know','ระบุลักษณะเด่นและเอกลักษณ์ของดนตรีในท้องถิ่น'),
('P3','ศ 2.2','ARTS-P3-21',21,'should_know','ระบุความสำคัญและประโยชน์ของดนตรีต่อการดำเนินชีวิตของคนในท้องถิ่น'),
('P3','ศ 3.1','ARTS-P3-22',22,'must_know','สร้างสรรค์การเคลื่อนไหวในรูปแบบต่าง ๆ ในสถานการณ์สั้น ๆ'),
('P3','ศ 3.1','ARTS-P3-23',23,'must_know','แสดงท่าทางประกอบเพลงตามรูปแบบนาฏศิลป์'),
('P3','ศ 3.1','ARTS-P3-24',24,'should_know','เปรียบเทียบบทบาทหน้าที่ของผู้แสดงและผู้ชม'),
('P3','ศ 3.1','ARTS-P3-25',25,'should_know','มีส่วนร่วมในกิจกรรมการแสดงที่เหมาะสมกับวัย'),
('P3','ศ 3.1','ARTS-P3-26',26,'should_know','บอกประโยชน์ของการแสดงนาฏศิลป์ในชีวิตประจำวัน'),
('P3','ศ 3.2','ARTS-P3-27',27,'should_know','เล่าการแสดงนาฏศิลป์ที่เคยเห็นในท้องถิ่น'),
('P3','ศ 3.2','ARTS-P3-28',28,'must_know','ระบุสิ่งที่เป็นลักษณะเด่นและเอกลักษณ์ของการแสดงนาฏศิลป์'),
('P3','ศ 3.2','ARTS-P3-29',29,'should_know','อธิบายความสำคัญของการแสดงนาฏศิลป์')
)
INSERT INTO learning_objectives(topic_id,code,name,sequence_no,status)
SELECT t.id,x.code,x.name,x.seq,'active' FROM seed x JOIN learning_topics t ON t.code=x.standard_code JOIN learning_skills sk ON sk.id=t.skill_id AND sk.code='ARTS' JOIN learning_subjects s ON s.id=sk.subject_id AND s.code='ARTS' ON CONFLICT(topic_id,code) DO UPDATE SET name=EXCLUDED.name,sequence_no=EXCLUDED.sequence_no,status='active',updated_at=now();
