('P2','ศ 3.2','ARTS-P2-24',24,'must_know','เชื่อมโยงสิ่งที่พบเห็นในการละเล่นพื้นบ้านกับสิ่งที่พบเห็นในการดำรงชีวิตของคนไทย'),
('P2','ศ 3.2','ARTS-P2-25',25,'should_know','ระบุสิ่งที่ชื่นชอบและภาคภูมิใจในการละเล่นพื้นบ้าน'),
('P3','ศ 1.1','ARTS-P3-01',1,'should_know','บรรยายรูปร่าง รูปทรงในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์'),
('P3','ศ 1.1','ARTS-P3-02',2,'should_know','วาดภาพถ่ายทอดความคิด ความรู้สึกจากเหตุการณ์ชีวิตจริง โดยใช้เส้น รูปร่าง รูปทรง สี และพื้นผิว'),
('P3','ศ 1.1','ARTS-P3-03',3,'should_know','ระบุวัสดุ อุปกรณ์ที่ใช้สร้างผลงานเมื่อชมงานทัศนศิลป์'),
('P3','ศ 1.1','ARTS-P3-04',4,'should_know','มีทักษะพื้นฐานในการใช้วัสดุ อุปกรณ์สร้างสรรค์งานปั้น'),
('P3','ศ 1.1','ARTS-P3-05',5,'should_know','บรรยายเหตุผลและวิธีการในการสร้างงานทัศนศิลป์ โดยเน้นถึงเทคนิค และวัสดุ อุปกรณ์'),
('P3','ศ 1.1','ARTS-P3-06',6,'must_know','จำแนกทัศนธาตุของสิ่งต่าง ๆ ในธรรมชาติ สิ่งแวดล้อม และงานทัศนศิลป์ โดยเน้นเรื่องเส้น สี รูปร่าง รูปทรง และพื้นผิว'),
('P3','ศ 1.1','ARTS-P3-07',7,'must_know','วาดภาพ ระบายสีสิ่งของรอบตัว'),
('P3','ศ 1.1','ARTS-P3-08',8,'must_know','ระบุสิ่งที่ชื่นชมและสิ่งที่ควรปรับปรุงในงานทัศนศิลป์ของตนเอง'),
('P3','ศ 1.1','ARTS-P3-09',9,'should_know','ระบุและจัดกลุ่มของภาพตามทัศนธาตุที่เน้นในงานทัศนศิลป์นั้น ๆ'),
('P3','ศ 1.1','ARTS-P3-10',10,'should_know','บรรยายลักษณะรูปร่าง รูปทรงในงานการออกแบบสิ่งต่าง ๆ ที่มีในบ้านและโรงเรียน'),
('P3','ศ 1.2','ARTS-P3-11',11,'must_know','เล่าถึงที่มาของงานทัศนศิลป์ในท้องถิ่น'),
('P3','ศ 1.2','ARTS-P3-12',12,'should_know','อธิบายเกี่ยวกับวัสดุอุปกรณ์และวิธีการสร้างงานทัศนศิลป์ในท้องถิ่น'),
('P3','ศ 2.1','ARTS-P3-13',13,'must_know','ระบุรูปร่างลักษณะของเครื่องดนตรีที่เห็นและได้ยินในชีวิตประจำวัน'),
('P3','ศ 2.1','ARTS-P3-14',14,'must_know','ใช้รูปภาพหรือสัญลักษณ์แทนเสียงและจังหวะเคาะ'),
('P3','ศ 2.1','ARTS-P3-15',15,'must_know','บอกบทบาทหน้าที่ของเพลงที่ได้ยิน'),
('P3','ศ 2.1','ARTS-P3-16',16,'must_know','ขับร้องและบรรเลงดนตรีง่าย ๆ'),
('P3','ศ 2.1','ARTS-P3-17',17,'must_know','แสดงความคิดเห็นเกี่ยวกับเสียงดนตรี เสียงขับร้องของตนเองและผู้อื่น'),
('P3','ศ 2.1','ARTS-P3-18',18,'should_know','เคลื่อนไหวท่าทางสอดคล้องกับอารมณ์ของเพลงที่ฟัง'),
('P3','ศ 2.1','ARTS-P3-19',19,'should_know','นำดนตรีไปใช้ในชีวิตประจำวันหรือโอกาสต่าง ๆ ได้อย่างเหมาะสม'),
('P3','ศ 2.2','ARTS-P3-20',20,'should_know','ระบุลักษณะเด่นและเอกลักษณ์ของดนตรีในท้องถิ่น'),
('P3','ศ 2.2','ARTS-P3-21',21,'should_know','ระบุความสำคัญและประโยชน์ของดนตรีต่อการดำเนินชีวิตของคนในท้องถิ่น'),
('P3','ศ 3.1','ARTS-P3-22',22,'must_know','สร้างสรรค์การเคลื่อนไหวในรูปแบบต่าง ๆ ในสถานการณ์สั้น ๆ'),
('P3','ศ 3.1','ARTS-P3-23',23,'must_know','แสดงท่าทางประกอบเพลงตามรูปแบบนาฏศิลป์'),
('P3','ศ 3.1','ARTS-P3-24',24,'should_know','เปรียบเทียบบทบาทหน้าที่ของผู้แสดงและผู้ชม'),
('P3','ศ 3.1','ARTS-P3-25',25,'should_know','มีส่วนร่วมในกิจกรรมการแสดงที่เหมาะสมกับวัย'),
('P3','ศ 3.1','ARTS-P3-26',26,'should_know','บอกประโยชน์ของการแสดงนาฏศิลป์ในชีวิตประจำวัน'),
('P3','ศ 3.2','ARTS-P3-27',27,'should_know','เล่าการแสดงนาฏศิลป์ที่เคยเห็นในท้องถิ่น'),
('P3','ศ 3.2','ARTS-P3-28',28,'must_know','ระบุสิ่งที่เป็นลักษณะเด่นและเอกลักษณ์ของการแสดงนาฏศิลป์'),
('P3','ศ 3.2','ARTS-P3-29',29,'should_know','อธิบายความสำคัญของการแสดงนาฏศิลป์')
)
INSERT INTO learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes,indicator_classification)
SELECT o.id,c.id,g.id,x.seq,x.classification='must_know','OBEC 2021 Arts must-know/should-know indicator.',x.classification FROM seed x JOIN learning_objectives o ON o.code=x.code JOIN learning_topics t ON t.id=o.topic_id AND t.code=x.standard_code JOIN learning_skills sk ON sk.id=t.skill_id AND sk.code='ARTS' JOIN learning_subjects s ON s.id=sk.subject_id AND s.code='ARTS' JOIN learning_curricula c ON c.code='TH-BASIC-CORE-2008-2017' JOIN learning_grade_levels g ON g.curriculum_id=c.id AND g.code=x.grade ON CONFLICT(objective_id,curriculum_id,grade_level_id) DO UPDATE SET sequence_no=EXCLUDED.sequence_no,required=EXCLUDED.required,notes=EXCLUDED.notes,indicator_classification=EXCLUDED.indicator_classification,updated_at=now();
commit;